  workOrderProcessDistribution(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        productionOperators
        requiredQuantity
        setupOperators
        scheduledFinishAt
        scheduledStartAt
        workOrderProcess {
          code      
        }
        workOrder {
          id
          number
          promiseAt
        }
        workcenter {
          calendarId
        }
      }
    }
  }
}

