{
  "payload": $.workOrderProcessDistribution.edges.node.{
    "create": {
      "id": id,
      "calendarId": workcenter.calendarId,
      "calendarEventTypeId": "unavailable",
      "title": "#" & workOrderProcess.code & " (" & requiredQuantity & ")",
      "priority": 100,
      "eventJson": {
        "allDay": false,
        "recurring": false,
